import{_ as E,H as t,f as a,i}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"第三十九封信-看完照片儿以后我们要干什么？","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第三十九封信-看完照片儿以后我们要干什么？.md","filePath":"去无方向的信/第三十九封信-看完照片儿以后我们要干什么？.md","lastUpdated":1795542896000}'),s={name:"去无方向的信/第三十九封信-看完照片儿以后我们要干什么？.md"};function o(n,e,B,r,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="第三十九封信-看完照片儿以后我们要干什么" tabindex="-1">第三十九封信-看完照片儿以后我们要干什么？ <a class="header-anchor" href="#第三十九封信-看完照片儿以后我们要干什么" aria-label="Permalink to &quot;第三十九封信-看完照片儿以后我们要干什么？&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B8%2589%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E7%259C%258B%25E5%25AE%258C%25E7%2585%25A7%25E7%2589%2587%25E5%2584%25BF%25E4%25BB%25A5%25E5%2590%258E%25E6%2588%2591%25E4%25BB%25AC%25E8%25A6%2581%25E5%25B9%25B2%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B8%2589%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E7%259C%258B%25E5%25AE%258C%25E7%2585%25A7%25E7%2589%2587%25E5%2584%25BF%25E4%25BB%25A5%25E5%2590%258E%25E6%2588%2591%25E4%25BB%25AC%25E8%25A6%2581%25E5%25B9%25B2%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B8%2589%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E7%259C%258B%25E5%25AE%258C%25E7%2585%25A7%25E7%2589%2587%25E5%2584%25BF%25E4%25BB%25A5%25E5%2590%258E%25E6%2588%2591%25E4%25BB%25AC%25E8%25A6%2581%25E5%25B9%25B2%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B8%2589%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E7%259C%258B%25E5%25AE%258C%25E7%2585%25A7%25E7%2589%2587%25E5%2584%25BF%25E4%25BB%25A5%25E5%2590%258E%25E6%2588%2591%25E4%25BB%25AC%25E8%25A6%2581%25E5%25B9%25B2%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/2.png" alt=""></a></p><p>生生：</p><p>你好哇。</p><p>上次拿 Trent Parke 的一张照片儿，讲了讲我们在学习拍照片儿的过程中，应该怎么拆解一张照片儿的技术信息，其实没有太多深奥的东西，就是那老几样来回来去地权衡就好了。</p><p>会了那个方法以后，我们就可以分析很多照片儿了，尤其是之前那些用 28mm、35mm 和50mm 的人拍的那些纪实照片儿，比如这张：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B8%2589%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E7%259C%258B%25E5%25AE%258C%25E7%2585%25A7%25E7%2589%2587%25E5%2584%25BF%25E4%25BB%25A5%25E5%2590%258E%25E6%2588%2591%25E4%25BB%25AC%25E8%25A6%2581%25E5%25B9%25B2%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B8%2589%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E7%259C%258B%25E5%25AE%258C%25E7%2585%25A7%25E7%2589%2587%25E5%2584%25BF%25E4%25BB%25A5%25E5%2590%258E%25E6%2588%2591%25E4%25BB%25AC%25E8%25A6%2581%25E5%25B9%25B2%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/3.png" alt=""></a></p><ul><li>Sergio Larraín</li></ul><p>通过照片儿里的蛛丝马迹，我猜这张照片儿是用 28mm 镜头拍的，对焦距离设置在了 2m处，大概的曝光参数是 1/60s F4 ISO400。这个参数表明，1958 年伦敦地铁贝克街站的亮度跟我们现在地铁里的亮度差不多，顶多一档曝光的事儿。</p><p>但我觉得我很可能会错估，不过没关系，我们可以查一查：</p><p>首先，我查到了一些当时的文献照片儿，甚至还有差不多那个时期的纪录片资料，在图像里我感受了一把，好像跟我想的差不多。</p><p>接着，我查到了一篇关于现代伦敦地铁照明的分析文章，从文章中可以读出伦敦人好像特别在意他们的地铁，特别喜欢给他们的地铁换灯泡，只要有新型灯泡，他们就会安上试一试。所以我猜，虽然从 1958 年到现在，伦敦地铁肯定已经进行过很多次照明系统改造了，但即便在1958 年，他们地铁的照明情况应该也不会太差。</p><ul><li>&quot; The underground has always been at the forefront of innovation, using the latest cutting-edge lighting technology. Over the years, this has included fluorescent lighting (with semi-resonant control gear for greater reliability), ceramic metal halide lighting, visible-spectrumlight emitting diodes (LED), compact fluorescent energy-saving lamps, electronic energysaving lamps, high-frequency T8 Fluorescent fittings, T5 cool-tip fluorescent lamps and,more recently, white LED light fittings. LEDs are now the preferred lighting technology inmost industries. &quot;</li></ul><p>紧接着，文章写到了后面，又贴出了一个 TheGreenAge 给出的关于室内照明的节能建议，他们说在扶梯或走廊这样的区域，100 lux 的光照强度就够了，厕所和机房 150 lux，而伦敦地铁的站台用的就是 150 lux 这个标准……还有，人群聚集的区域要 300 lux，而且是至少 300lux。</p><ul><li>&quot; 100 lux – Sufficient for lifts, corridors, stairs and areas that are transitory for occupants</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>and don&#39;t require any detailed work. Also warehouse areas and bulk stores. Not bright</span></span></code></pre></div><ul><li><p>enough to read a book, but good enough for people to get around without injuringthemselves and see where they are going.</p></li><li><p>150 lux – Restrooms and plant rooms. This is the level used by London Underground forplatforms and which provides an adequate level of light for people to join and alight safelyfrom trains.</p></li><li><p>200 lux – Entrance areas and lobbies require this level of light, and it is also the minimumfor a restaurant dining area.</p></li><li><p>300 lux – Assembly areas, such as village halls, require at least 300 lux.</p></li><li><p>500 lux – Retail spaces should have this as a minimum light level, as should general officespaces. This level should be suitable for prolonged work on computers, machinery andreading.&quot;</p></li></ul><p>然后，我又查到一篇中国照明网发布的文章，《地铁车站照明系统能耗分析及节能对策》，里面提到了扶梯区域的照明标准是 150 lux，站台区域的照明标准是 200 lux，但研究员的实测是，扶梯区域目前的光照强度不够 150 lux ，而站台区域的光照强度高于 200 lux。接着，研究员根据实际情况分析，得出结论，说这是不对的，站台其实不用那么亮，而扶梯区域反而不能暗，因为扶梯区域比站台区域更忙叨，更容易出事儿。</p><ul><li>“制定合理的设计标准是节能的基础。乘客上下地铁站台的拥挤程度高于站厅，扶梯和楼梯的拥挤程度又高于站台。由表 3 可知，站厅照度标准 (200 lux) 高于楼梯和自动扶梯照度标准 (150 lux)，显然不合理。建议照度的设计标准应该与人群的拥挤程度成一定比例。”</li></ul><p>所以，我想，伦敦地铁估计也不会听那个什么 TheGreenAge 的话，反正，搞来搞去，就说明现代地铁的照明标准，伦敦和中国真的是差不多的。但这也并不能说明 1958 年伦敦地铁的照明情况啊，对吧？</p><p>不过不重要了，我也不再继续查了，因为我已经开始不感兴趣了。等有机会我去伦敦，我要去贝克街，先去看看夏福，然后到地铁站里，用 1/60s F4 ISO400 这组参数拍一张照片儿，看看这个参数准不准，不准也没关系，不准的话就看看差多少，然后我相信我拿着相机就能平趟伦敦地铁了。</p><p>但一想到要拿着相机平趟伦敦地铁，我就马上又想到了一个问题，那就是，在伦敦，在伦敦地铁里，能不能随便拍照片儿？有没有相关法律规定？于是，我就又查到了这么一篇文章：Tipsfor London Underground Photography</p><p><a href="https://www.photocrowd.com/blog/183-tips-london-underground-photography/%E6%88%91%E4%B8%8D%E7%9F%A5%E9%81%93%E7%9C%8B%E5%88%B0%E8%BF%99%E5%84%BF%EF%BC%8C%E4%BD%A0%E6%9C%89%E6%B2%A1%E6%9C%89%E6%98%8E%E7%99%BD%E8%BF%99%E5%B0%81%E4%BF%A1%E5%9C%A8%E8%AF%B4%E4%BB%80%E4%B9%88%E2%80%A6%E2%80%A6%E6%B2%A1%E5%85%B3%E7%B3%BB%EF%BC%8C%E6%88%91%E4%BB%AC%E8%BF%98%E6%9C%89%E4%B8%80%E4%BB%B6%E4%BA%8B%E5%84%BF%E8%A6%81%E8%AE%B2%E5%91%A2%E3%80%82" target="_blank" rel="noreferrer">https://www.photocrowd.com/blog/183-tips-london-underground-photography/我不知道看到这儿，你有没有明白这封信在说什么……没关系，我们还有一件事儿要讲呢。</a></p><p>我看照片儿已经养成分析照片儿的习惯了，我说过，用不了多少时间，熟练了以后，就是脑子里的一闪而已，不费事儿，所以这个习惯在我这么懒的人这儿也可以得以保留，而且越来越驾轻就熟。但突然有一天，我看到这么一组照片儿：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B8%2589%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E7%259C%258B%25E5%25AE%258C%25E7%2585%25A7%25E7%2589%2587%25E5%2584%25BF%25E4%25BB%25A5%25E5%2590%258E%25E6%2588%2591%25E4%25BB%25AC%25E8%25A6%2581%25E5%25B9%25B2%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B8%2589%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E7%259C%258B%25E5%25AE%258C%25E7%2585%25A7%25E7%2589%2587%25E5%2584%25BF%25E4%25BB%25A5%25E5%2590%258E%25E6%2588%2591%25E4%25BB%25AC%25E8%25A6%2581%25E5%25B9%25B2%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/4.png" alt=""></a></p><ul><li>Vera Torok &amp; Robert Pap</li></ul><p>我最早看见这组照片儿是因为他们入围了 Leica 的奥斯卡巴纳克奖 (Leica Oskar BarnackAward) 的决赛，这是什么奖，你可以自己查一下。</p><p>当时我打开的是作品展示页面，没有任何文字说明，所以我就很自然地开始猜技术参数，我就臆想这些照片儿是怎么拍的，臆想当时的拍摄环境，臆想这些镜面反光的观察难度和拍摄难度，我甚至还在想，她如果发现了一个她心仪的镜面，会不会先帮人家擦玻璃……这组照片儿太难搞了，脑子完全乱掉了，就这样臆想了半天，我突然想到，好像应该看看作品介绍。</p><p>于是我往下翻，翻到了一个 &quot; More about Vera Torok &quot; 的链接，点进去以后是一篇很简短的作品介绍，我这才知道这不是单纯地满大街找镜面反光，这是多重曝光的效果，而且摄影师提到了她的一个合作伙伴，叫 Robert Pap……但她只是提到了这个人，这个人是干嘛的，他们是怎么合作的，我不知道。</p><p>于是，我就继续查，查到了一篇访谈，里面说到她有一次把已经拍过的胶卷不小心又装进相机了，等洗出来一看，看嗨了，所以这种效果的起始是因为一次失误，而 Robert Pap，是跟她一起完成这个项目的人。</p><p>他们俩各自先拍，然后换胶卷，装进相机再拍一次，最后洗出来看，虽然这是两个人不同视角的结合，但过程中两个人还是需要不断地调整拍摄策略，比如试验画面的明暗比例怎么分配会更适合双曝，哪些颜色双曝或组合在一起之后会更协调，综合来看，两个什么样的场景结合出来会更好看……最后，他们俩拍了四年，从很多很多照片儿中选出了这几张参赛。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在这篇访谈的底下，有一个 &quot; Discover more of Vera and Robert&#39;s work &quot; 的链接，我点进去</span></span></code></pre></div><p>以后发现是一个黄色网站，问我满没满 18 岁，我一想，我还没满 18 岁，就把那个网站给关了。</p><p>继续，我查 Vera 的生平，查到她还有其他个人项目，于是继续往下查……我不知道看到这儿，你有没有明白这封信在说什么。</p><p>咱们之后有时间再聊。</p>',36)])])}const g=E(s,[["render",o]]);export{h as __pageData,g as default};
